'醉中写出矾山歌，梦中飞入矾山路',
'挥金酾酒少时事，一笑昨梦何澜翻',
'八年如昨日，一梦隔平生',
'夜夜还乡梦，年年异县秋',
'四海共知坡下路，昔人犹想梦中归',
