'空山无人下群仙，似梦非梦或告旃',
'一梦经年归去好，宦情全薄此情深',
'梦到家园归自好，起寻官路去何长',
'已晴复雨雨还晴，惯阅人间梦不惊',
'三年不唤清溪渡，梦里瀼西春水路',
