'吴霜有信镜先知，楚雨无踪梦自迷',
'唤起三年梦中意，想见诗成清可掬',
'九年清梦落鸣珂，尊酒相逢奈乐何',
'一夜梅坡清入梦，不妨持恼谢岩人',
