'一枕凉风吹梦去，楚山修竹正如云',
'梦回无个事，风雨度前山',
'梦回人不见，心醉兀悠悠',
'黄粱一夜梦，白雪数人诗',
'舣舟洞庭三日雪，一梦十年今白发',
'秋月耿寒林，时来梦中否',
