'卧龙山下听吟松，细雨清明似梦中',
'忧心不能寐，无梦得相逢',
'梦魂思一遇，风雨暗长淮',
'山川烽外远，岁月梦中长',
'千古苍茫青史梦，一年迢递故乡心',
'有梦合寻苕水路，何心更种马塍花',
