'风撼塔铃天半语，众人都向梦中闻',
'笑问月边人在否，中宵有梦到钧天',
'繁华一梦里，风雨十年间',
'年来懒作少年狂，一枕功名属梦乡',
'勋阁麒麟无梦想，故山猿鹤有心期',
