'梦得惊人句可疑，室中酬话恰相宜',
'夜来梦入宸奎阁，户牖重开见日轮',
'道人无妄想，梦不到南柯',
'半窗明月三更梦，一枕西风两鬓秋',
'年来不作功名梦，老去全休富贵心',
'花怯晓风寒蝶梦，柳愁春雨湿鶑声',
'道人不作阳台梦，纸帐梅花伴独眠',
'清阴满地无人迹，一径松风鹤梦寒',
'随风粉翅太轻狂，夜宿花房春梦香',
