'百年岁月心难老，万里江山梦已驰',
'归来一梦觉，东窗又明发',
'山深梦断不可觅，落花耿耿寒梅枝',
'青山唤醒十年梦，明月空怀千里思',
'拥炉兀兀坐成睡，梦到家山人不知',
'梦中识归涂，踏遍孤山月',
'至人本无梦，有梦其何伤',
'若非一鞭醒寒梦，梅柳争春无了时',
'醉眠春一榻，不记梦伊何',
'夜来听雨梦仇溪，梦觉招邀客赋诗',
'月照空梁几梦中，翩然环佩下天风',
'故里未归先入梦，新交虽好少知心',
