'空山月落春风换，直作罗浮梦里看',
'两株横卧处士桥，梦中归踏孤山月',
'青鸟梦中见，畏来花下飞',
'去来似尔勿复道，白下钟山梦中老',
'夜长春度梦，门雪拥笆篱',
'梦魂惊断梨花月，寂寞五更风雨寒',
'孤楼不作还家梦，卧听松风响夜长',
'边风吹碎心如梦，云长只有孤鸿送',
'梦熟不知衾似铁，睡醒何用酒盈缸',
'梦里不知时世换，买珠犹自说京华',
'人在西风何处梦，书回南雁隔年愁',
