'春树相思白日晚，月梁入梦青灯夕',
'梦觉黄粱仅一炊，人生适意不多时',
'风搅一枝香梦醒，四天烟景夜茫茫',
'不见沧洲已十霜，梦中炯炯此灵光',
'梦绕明月湾，水清见石底',
'梦觉不同均是梦，寂然妙在不闻时',
'出山两足涴尘土，几夜梦听山中泉',
'往日相从不知乐，只今说梦竟徒劳',
'千里怀人黯风雨，五更归梦到松柟',
'千里相望劳远梦，六年不见耿深情',
'自读仲退诗，夜夜梦见君',
