'蛙鸣莫夜官何为，蝶恋芳菲梦不知',
'鼙鼓鞭月行春雷，洞房花梦酣不回',
'昨夜相逢处，朦胧春梦中',
'相思不可见，清梦绕江𣸣',
'梦寐不忘我湔祓，谓曷一语能近道',
'更欲强招年少客，折花同赏梦中春',
'云山劳梦想，风日幸晴明',
'一年春事五更初，梦觉寒香乍有无',
