'口诵离骚手遮日，梦魂不敢到长安',
'薄日花光怀杜曲，清流竹色梦山阴',
'可怜羁客梦，夜夜在家乡',
'夜雨喧客耳，羁梦何由成',
'径过物色尽可记，至今夜梦当时游',
'兴衰春梦短，人世谅何求',
'羡子还来觐丘陇，益令归梦绕金山',
'梦里空惊岁月长，觉时追忆始堪伤',
'爱惜分阴成底用，不如恶梦早醒来',
'梦中射落蟭螟窠，开眼看来无缝罅',
'海燕坐间谈实相，泥人梦里获真如',
'头陀头陀休趁哄，一世初无一炊梦',
'真个溪山看似梦，却将水墨写溪山',
