'东山说偈梦石纪，见者悉成无上觉',
'武陵归去探年华，扬州一梦烟波远',
'洒落风轩枕簟凉，高眠亭午梦何长',
'空山冥冥云雾窗，春风好梦欹残缸',
'携家来作闽海梦，三年客食天南陬',
'梦中一叶摇江湖，困睡不觉身蓝舆',
'忆挽梅花与君别，终年梦挂南台月',
'归来疑梦断，清境皎不昧',
