'不用新诗摹绝境，定知长到梦魂间',
'午窗唤起梦魂好，一语便知风味真',
'绕屋风篁梦寐清，住山活计几时成',
'花裁栗玉秋风健，香近龙涎晓梦知',
'祀先不暇尝，一夜惊入梦',
'故乡空费梦，来此听谿声',
'梦中失脚在何许，千里闽越天南隈',
'以兹一梦顷，可况百年遇',
'七日梦楹终有待，三年筑室恨无从',
'梦中从我游，子猷推第一',
'梦寐无忧眠可熟，清虚自积体尤强',
'江山不隔梦千里，鸿雁欲归书数行',
'旧事老年多记忆，故园归梦正悠飏',
'烟尘无复音书到，魂梦犹疲道路长',
'铁夫破梦五更前，石人开眼一壶天',
'转侧木人惊梦破，雪芦满眼不成眠',
'一唤唤回春梦破，千山浑作木龙吟',
'其如樽酒情难忘，恍然一梦五云乡',
'燕麦兔葵僧舍里，何如梦得访桃花',
'三语风流归梦想，十年书问寄浮沉',
'夜梦俞音出帝闱，朝来江雨已生肥',
'当年梦赉见清伊，劲气全归目与眉',
'儿钓童游几梦思，春风千里恨归迟',
'昨梦饱经全盛日，此生俄叹始衰年',
'自笑玉川空两腋，清风无梦到蓬莱',
'千山路远劳魂梦，一纸书来强笑欢',
'梅花如梦李成尘，却伴酴醾过晚春',
'祇应两庵有归梦，梦到花下奚复疑',
'帝乡怜久客，归梦亦何心',
'夜短无清梦，年高叹幻身',
'云带竹光天外碧，风回松吹梦中醒',
'海上伤心一卮酒，梦魂先已酹重闱',
'升阶子细瞻尧日，不似侏儒梦灶年',
'故山萝蔓锁云扉，几夕扁舟已梦归',
'闽月长留梦，吴门自是仙',
'倦枕不烦神栎梦，有人无用亦常叹',
'客来鱼鸟皆知乐，梦罢池塘并得春',
'欹枕风窗雪絮繁，梦回红日转南轩',
'士龙犹记当时梦，梦想如今海上城',
'寄榻若无千里梦，便如云衲一孤僧',
'忽得新诗知节物，衰迟浑似梦中人',
'只应今夜相思梦，同渡江云水石间',
'从此梦魂应逐汝，南云夜夜过鄞江',
'雨著梨花春已老，烟沉芳草梦犹寒',
'欹枕梦能归故隠，满帆烟雨渡涛江',
'江湖有梦追前事，天地无根笑此生',
'芥台如臂何曾梦，菜脑生筋漫自供',
'数椽书屋守蛛丝，一出三年梦见稀',
'一梦江湖已十春，芒鞋不践马头尘',
'犹嫌百年梦，剩此一枝筇',
'草堂人去空旧赏，梦入江山半明灭',
'晚岸云低月，相随照梦归',
'急雨打成今夜梦，孤灯挑动昔年愁',
'迎年送腊须臾梦，正似须弥不动时',
'雨滴梧桐河汉淡，梦回犹记少年心',
'梦回一枕凄凉恨，账外青灯不得知',
'梦境相逢便相别，万峰秋色正磨天',
'蝴蝶梦中新岁病，杜鹃声里故乡心',
'癯儒自昔有仙骨，夜梦体飞如叶轻',
'逐鹿营营一梦惊，事随流水去无声',
'不解小山招隠意，岩幽归梦绕青丛',
'几年归梦水云间，猿鹤重寻已厚颜',
'一秋梦桂仙洲碧，盘礴才能半日中',
'何如金丸走衾枕，三月梦游薝卜林',
'朝阳照破兴亡梦，一径花阴自绿苔',
'九九算来成底梦，休休归去复何疑',
'蓦地梦回头，长天飞一鹗',
'行止非人十年梦，废兴有命一浮家',
'放逐归来户已篷，梦魂时到浙江东',
'须臾寝不梦，觉来日升东',
'万事等一梦，寸心当自安',
'马嚼青刍喧夜寂，人围绿幕梦归期',
'一生梦幻本如此，过眼浮云安在哉',
'千里云山通梦想，十年笑语隔心期',
'梦回一夜频搔首，肠断空阶骤雨声',
'梦魂历尽百城余，觉后端知一物无',
'云梦胸中吞八九，了无官事苦相关',
'梦魂正入无何有，谁著长钩恼睡蛇',
'鸡窗不梦笔头花，分合扶犂霅水涯',
'时令清夜里，梦绕云水湾',
'纵不能得到，夜梦必见之',
'一从秋到天宇清，颇费梦思眠不熟',
'相思愁梦断，一见笑颜开',
'须知世事浑如梦，还念人生尽若浮',
'苦无佳况人空老，数尽残更梦不成',
'世事转头如蝶梦，人生到此似蘧庐',
'苦恨欲归无羽翼，夜深魂梦只悠飏',
'经年不见梦魂飞，依旧仙装淡薄衣',
'一病兼旬百不禁，愈牵归梦绕家林',
'别来星纪两周天，梦想风标每慨然',
'唯是平生爱风月，致令清夜梦池塘',
'盍簪经岁遽分襟，夜夜相思梦里寻',
'春来池馆浑如旧，梦觉黄粱事已空',
'今宵烛下匆匆看，犹恐归来似梦中',
'惊破梦魂何可恨，得知身在浙江头',
'胸中有云梦，略不见芥蒂',
'至人本无梦，偶梦非谬悠',
'觉来无一事，追梦续新诗',
'晓来春到西窗外，唤梦一声黄栗留',
'挥毫不作惊人语，句法由来似梦间',
'人世百年都是梦，醉乡四达总无门',
'无人惊午梦，双蝶下花丛',
'那知商帝梦中形，远近搜求不容伏',
'风吹枕席清无梦，烟覆江城晓变春',
'东风吹梦去，一见貌颀颀',
'梦草池塘如有得，对床风雨亦非艰',
'精神愦愦如痴梦，赢得时时病在身',
'故乡归未得，飞梦入青天',
'他时梦中路，留眼记所更',
'残梦不能全省记，半随风雨过东街',
'我昔梦见之，青衫水仙郎',
'如何虀盐厨，便谓酒肉梦',
'想见东家中夜梦，犹与公孙同衮舄',
'峡云春梦远，江月夜珍藏',
'雪霜寒谷残年后，云雨阳台昨梦空',
'洗我昆仑心，充我云梦胸',
'何须著胸中，云梦一芥蒂',
'不知纷纭梦几许，觉来烟际闻昏钟',
'茂陵先帝傥见梦，敢不奏记通天台',
'酿成无边春，吞此云梦泽',
'午窗睡美无人唤，梦逐游丝自在飞',
'愁横蜀岭何年断，梦绕吴江尽日流',
'梦觉五更山月上，溪边人语钓船移',
'霜雪半头明镜里，江湖归梦野鸥前',
'无端却被东风误，又作恩平一梦回',
'管辂相无壬甲寿，郑玄梦告己辰年',
'午窗归梦无人唤，银叶龙涎香渐销',
'钓艇江湖千里梦，客毡风雪十年寒',
'三年京国梦，一柱立不能',
'看了青灯梦不成，东风辊雪落寒声',
'招魂拟向横阳道，有梦长飞霅水滨',
'梦魂未到乡无何，起来搔首空吟哦',
'刘郎何事久无书，梦里频频却见渠',
'山前十里雪，夜入梦魂香',
'七年娇姹慰衰翁，回首追思一梦中',
'见说有时魂梦里，化为蝴蝶绕花旁',
'枕冷梦自清，夜明窗更炯',
'须信精诚可动天，高宗一梦得真贤',
'石桥未到已先知，入眼端如入梦时',
'我来岁及周，梦寐怀清风',
'谢池一别真成梦，鉴水相逢似有缘',
'端似中山梦得诗，海中仙果子生迟',
'池塘有梦吟春草，屏障无心恋绮霞',
'人间一梦觉，卿月堕台城',
