'鶑来似结啼鸾怨，蝶散应知梦雨狂',
'数年不侍御炉傍，梦断千山隔帝乡',
'主人当日孤真赏，魂梦还应屡到来',
'梦符蚌腹生珠夜，事应台躔捧日时',
'江山不隔还乡梦，昨夜迢迢到佛庐',
'一夜孤舟浪打头，不容客梦到沧洲',
'当年把臂入龙山，犹记相逢醉梦间',
'我曾魂梦到西南，翠碧相围远近山',
'他日西窗剪银烛，巴山却话梦中游',
'准拟小轩添睡美，梦成风雨夜翻江',
'梦中要渡深溪水，伎俩多般进不能',
'梦里思归黄檗山，无端平地堆青嶂',
'瞿塘不可上，秋梦长颠倒',
'惊起河波理残梦，十年灯火上心来',
'梦生羽翼不可逐，想象风景空吟哦',
'梦魂夜夜到君边，觉来寂寞鸳衾独',
'我今梦中说，说者觉如义',
'自拜梦中人，妄想从谁立',
'相逢谁觉梦中梦，浪静闲乘般若舟',
'却将梦说梦，何日得超升',
'祇这一株惊被梦，令知大地百花新',
'移转亦何难，梦梦如抱怏',
'梦过一年还是魇，心更万事竟成灰',
'焉知鱼乐我非鱼，梦里荣枯觉则无',
'只今中夜梦，突怒见潮波',
'惊回潼水梦，喜见义城春',
'又作吴中十年梦，胥山绝顶望西兴',
'悬知心更静，梦不到红尘',
'寒窗十载江湖梦，夜月三更风露秋',
'著粉直嫌妆太白，只今何似梦中时',
'梦中春草多佳句，一洗尘埃速寄将',
'归去池塘入新梦，句中芳草醉中茵',
'漫作剡中梦，难寻雪夜舟',
'世事一场梦，山栖冬复春',
'觥船相对百分空，京口追随一梦中',
'夙传天上誉，早梦月中名',
'此去恰如巫峡梦，相望千里事悠悠',
'梦中既不了，虽觉何足云',
'岂不舒我忧，熊罴梦丰年',
'明宵酒醒会相忆，梦绕百级凭飞栏',
'梦破清风吹雨脚，醉余新月上林端',
