'北渚青山劳我梦，西垣红药待君归',
'湖海周游未卜居，好山时一梦衡庐',
'却忆巴山旧时语，梦回窗竹已生花',
'云梦悬知八九吞，银山万叠涨天门',
'诵君好句浑如画，寄我清游梦想中',
'梦绕江南云水乡，麻姑坛下月如霜',
