'诗来唤起相思梦，又向梅山得楷模',
'赤脚有年供侍侧，青鸾无梦到人间',
'一别阻云水，相思劳梦魂',
'多少纷纷尘世人，梦中说梦元非真',
'一朝决去水赴壑，梦魂先到鹤山侧',
'桃李荫繁春不留，琼瑰梦断月空白',
'骊歌未残心欲动，剪烛夜谈如昨梦',
'胡为得此色为动，引赴幽人春草梦',
'空山行役偶相逢，物色看来与梦同',
'夜来春梦好，先已上觚棱',
'春梦断不记，春游谁与同',
'桃李春如寄，鸥鹇梦不惊',
'厌把五更供客梦，猛将一日了山程',
'心向青山贪未了，梦随白鸟去无由',
'为问何时到墙仞，清宵远梦故堪凭',
'岁晏客天无好梦，最怜清露渍人衣',
'一樽别酌心先醉，万里归桡梦易惊',
'只应昨夜幽窗梦，飞到君边未可知',
'空山冥冥云雾窗，春风好梦敧残缸',
'梦中一叶摇江湖，困睡不觉身篮舆',
'回首翔鸾一梦中，玉箫缓送成都酒',
'眼看世事等虚空，云梦胸中无一物',
'客来惊起还乡梦，绕屋春风绿树寒',
'往事明明是梦中，发霜那有旧形容',
'晨旌几碍观山目，夜柝翻惊梦月情',
'愁多空被酒，梦短不成归',
'何处飞来恼归客，小窗梦破正消魂',
'伫立茅檐一搔首，扶春梦月与谁分',
'后日重来携枕簟，不妨午梦到斜阳',
'酒薄饮难醉，山寒梦不成',
'何许秋声惊客梦，檐间不断一铃鸣',
'春来乡梦凭谁说，归去君恩未敢忘',
'五更欹枕一凄然，梦里扁舟水接天',
'山林不恨音尘远，梦寐时容笑语亲',
'抚事惊年往，怀人有梦知',
'孤枕有时莺唤梦，斜风无赖客添衣',
'浮生一梦耳，何者可庆吊',
'半世无归似转蓬，今年作梦到巴东',
'坐忆故人空有梦，尺书不敢到京华',
'亭驿驱驰髀肉消，故山归梦愈迢迢',
'梦里何曾有去来，高城无奈角声哀',
'唤起十年闽岭梦，赪桐花畔见红蕉',
