'我梦神君自天下，威仪奕奕难具陈',
'白首有诗悲蜀道，清宵无梦到钧天',
'我游故祠九顿首，夜遇神君了非梦',
'悬知今日梦，不隔重城键',
'濯锦豪华梦不通，岿然孤叠乱山中',
'客路更逢秋色晚，故山空有梦魂归',
'莺花又作新年梦，丝竹常闻静夜声',
'东风好为吹归梦，着我松江弄钓舟',
'少日壮心轻玉塞，暮年幽梦堕沧洲',
'欲赏园花先梦到，忽闻檐雨定心惊',
'五更风雨妨归梦，卧看残灯吐半缸',
'老子真成兴不浅，凭鞍归梦绕家山',
'判为梅花倒玉卮，故山幽梦忆疏篱',
'耿耿孤忠不自胜，南来清梦绕觚棱',
'人世绝知非昨梦，天真堪笑博浮名',
'空斋独夜萧萧雨，枕上诗成梦不成',
'空堂饱作东归梦，梦泊严滩月满舟',
'白浪黏天鲛鳄横，梦中识路亦何为',
'岂无佳山水，正尔寄梦想',
'心安了无梦，一扫想与因',
'此梦即今都打破，不妨寂寞住天涯',
'湖山旧隐入我梦，白首忘归独安取',
'夜作看花梦，朝赋饮酒诗',
'拟倩天风吹梦去，浩歌起舞散花楼',
'童颜绿鬓无人识，回首尘寰一梦残',
'只怪梦寻千里道，不知愁作几重城',
