'要知清梦游何许，不钓桐江即锦江',
'年来只有追欢梦，百舌无情又唤回',
'人生万事皆如梦，自笑区区记剑痕',
'点点滴滴雨到明，凄凄恻恻梦不成',
'梦回有恨无人会，枕畔橙香似昔年',
'当时说愁如梦寐，眼底何曾有愁事',
'梦到青羊看修竹，道人告我丹将熟',
'故故催诗衬雨蓬，悠悠破梦隔云钟',
'此生吾自断，不必梦邯郸',
'寄迹人间梦已长，新年脱帽始微霜',
'残年自喜身强健，又作清都梦一回',
'一壶花露拆黄縢，醉梦酣酣唤不譍',
'今朝忽破簿书梦，此地暂还风月身',
'陆氏经不经，周公梦不梦',
'无由一来过，梦想向岩谷',
'那能长作客，夜夜梦还家',
'信若此梦寐，岂不见颜色',
'谁谓死无知，每出辄来梦',
'三十年为一世人，孤城梦断洛阳尘',
'唤回四十三年梦，灯暗无人说断肠',
'剑外归耕梦不通，公车上疏路何从',
'老去无余念，时时梦弊庐',
'时人正作市朝梦，老子已成云水身',
'梦寄梅村竹坞间，不堪客里见春还',
'薄酒愁边供醉醒，故人梦里话悲欢',
'尔来作吏若堕阱，每一梦到心凄然',
'昨夜梦中行万里，莲华峰上听松风',
'我梦入烟海，初日如金镕',
'慨然此夕江湖梦，犹绕天山古战场',
'射虎南山无复梦，雨蓑烟艇伴渔翁',
'开眼不妨成一梦，翦翎何至羡群飞',
'世事说来犹可厌，宦情梦里亦应无',
