'老去已忘天下事，梦中犹看洛阳花',
'嵩云缑月年年梦，楚柁吴樯处处愁',
'长辞帝所梦，不愧草堂灵',
'欲泣老无泪，欲梦不可常',
'觉时不及梦差乐，死去始嗟生可怜',
