'士如天马龙为友，云梦胸中吞八九',
'酒渴喜闻疏雨滴，梦回愁对一灯昏',
'壮志可怜成昨梦，残年惟有事春耕',
'此生无复阳关梦，不怕樽前唱渭城',
'年来洗尽东陵梦，瓜垄萧萧老故园',
'远使有书常洒泪，长宵无梦更伤心',
'瑞锦已残犹有梦，明霞初散可无诗',
'泣至眼枯无血续，梦随魂断独心知',
