'平生养气心不动，黜陟虽闻了如梦',
'一身寄空谷，万里梦天山',
'日随香篆过，梦逐雨声长',
'巴山频入初寒梦，江月偏供独夜愁',
'交朋一散如天远，试向今宵梦里寻',
'雨声不贷三更梦，酒力宁禁万里愁',
'怀人悲梦短，听雨怯更长',
'梦中无远道，醉里失孤愁',
'平生梦亦不相接，忽然怀中泻珠玉',
'道业虽如诗不进，世缘已与梦俱空',
'朝朝问水神，夜夜梦三巴',
'梦回忽觉南风起，时听铮然一两声',
'龟紫拜恩如梦寐，残年其实一渔蓑',
'万里关河孤枕梦，五更风雨四山秋',
'桃花梦破刘郎老，燕麦摇风别是春',
