'狼藉残花满地红，拥衾孤梦雨声中',
'万里萧条酒一杯，梦魂犹自度邛郲',
'梦魂不可到，于此寄遐想',
'元知梦境无真实，不待邯郸觉后空',
'唤回二十年前梦，半醉姑溪棹月归',
'忽忽身如梦，迢迢日似年',
'梦为估客扬州去，水调声中月满船',
'大节艰危见，真心梦寐知',
'从此梦游端有地，渊明不独爱吾庐',
'雨声惊断长安梦，惆怅西窗夜半灯',
'赖有三峨梦，时时到枕中',
'那知蓬山梦，忽继此清绝',
'一扫枕中梦，即归江上村',
'清梦不知身万里，只言今夜宿葭萌',
'不听此声三十载，梦回搔首一凄然',
'往事已成孤枕梦，故人谁共一樽开',
'酣酣一枕睡，不觉幽梦长',
'重游惟有西窗梦，一点灯青梦不成',
'老来感旧多凄怆，孤梦时时到瀼西',
'功名不入闲人梦，诗酒犹关老子身',
'可怜老境萧萧梦，常在荒山破驿中',
'忽梦行军太行路，不惟无想亦无因',
'梦破江亭山驿外，诗成灯影雨声中',
'万里旌旗无昨梦，一蓑烟雨有新诗',
'旧事已无人共说，征途犹与梦相关',
'四海交情残梦里，一生心事断编中',
'每因清梦游敷水，自觉前身隐华山',
'功名不入山林梦，诗酒犹关老病身',
'未尝一事横胸次，但曲吾肱梦自长',
'自怜一觉寒窗梦，尚想浯溪石可磨',
'荣悴纷纷醉梦中，转头何事不成空',
'淡薄相遭心已懒，修行无力梦犹狂',
'客梦初回夜漏残，东村想见杏花繁',
'貂插朝冠金络马，多年不入梦魂中',
'一枕鸟声残梦里，半窗花影独吟中',
'醉中光景似得志，梦里朋侪如少时',
'世间真梦耳，何物可关心',
'青城上官叟，时入梦中来',
'梦里逢无咎，天涯哭季长',
'生世如梦境，淹速无定时',
'老来百念尽消磨，无奈云安入梦何',
'闲云不入老人梦，邻笛似知孤客愁',
'寂寂东窗午梦残，更堪春雨作春寒',
'春与人俱老，花随梦已空',
