'西游陈迹浩无穷，回首真同一梦中',
'可怜未遽忘风月，犹梦华觞插羽飞',
'吾生清绝烦君看，不枉人间梦一回',
'齑盐二十年前梦，尚想长廊撼夜铃',
'雨滴空阶怜夜榻，吟牵芳草梦春池',
'三世如来同一哄，大士亦作补陀梦',
'愚水端能勤入梦，崳峰何得懒相迎',
'梦里闽山月，吟边楚水波',
'梦岂花边到，春俄雨里迁',
'诗仙诗满云梦胸，那更相逢此花触',
'一夜秋声恼井桐，梦回得句寄西风',
'梦中若个韶州路，庾岭梅花正可怜',
'谩向世人谈昨梦，便来唤我作诚斋',
'呼酒撚花谈旧事，牡丹匹似梦中看',
'昨夜茅檐疏雨作，梦中唤作打篷声',
'唤醒渊明千载梦，政缘泸水一篇诗',
'酒力欺人正作眠，梦中得句忽醒然',
'夙怀山水心，梦寐向东越',
'夜梦登天坛，坛上两仙人',
'梅生不量仰天问，神官夜梦言语周',
'醉里不知家尚远，梦回忽觉路初长',
