'梦里长逢孟，羹中亦见颜',
'最是醉梦中，唤作松风雨',
'窗虚月白清无梦，却为西风数漏声',
'别去公怀我，诗来我梦公',
'不见子张子，令人梦亦思',
'醉梦那知蕉叶雨，小舟亲过蓼花滩',
'我眠亦甚安，梦中初无惊',
'如何作梦语，反侧意不平',
'我来秋浦政逢秋，梦里曾来似旧游',
'久别忽相逢，相对恍如梦',
