'冥冥千古今如梦，浩浩长江不管愁',
'一枕梦云过，半空诗雨来',
'梦和明月冷，心与白云飞',
'松花落地鸟声寂，一枕清风送梦回',
'夜半风吹远梦回，直从海上忽飞来',
'梦中也学云峰路，未老来游蒲涧山',
'梦幻之身不久长，桑榆能几耐风霜',
'身如纸帐梅花梦，心似香炉柏子灰',
'君生平事皆如梦，我两眉间不着愁',
'人在华胥初梦断，乱山满目一声鸦',
'归来车马如云拥，扫去簪缨似梦醒',
