'山村荷瓢感慨欹，买酒独赏春梦婆',
'追忆旧游如昨日，想君夜梦到西陵',
'死别日益远，年衰梦亦无',
'但觉梦回深夜爽，不知身在九霄眠',
'望切衮归基宥密，可能无梦到周公',
'松楸长夜梦，风露作晨征',
'春阴漠漠护轻寒，春昼无聊午梦闲',
