'夜来忽叶熊梦吉，凌晨果见生真才',
'他日成归梦，来兴楚子悲',
'一别三年远，相思入梦频',
'双溪风月只当年，客梦寻君屡慨然',
'欹枕夜深偷酒力，一声啼鸟梦初醒',
'只今未别先成梦，梦觉争如既别何',
'月上小窗人欲静，睡来清入梦魂香',
'新萤一点南窗下，来约灯花伴梦魂',
'浮沙篱落乱鸣蛩，永夜相寻客梦中',
'老去不知筋力减，夜阑犹梦解重围',
'惝恍纪一梦，浩不知涯津',
'十年尘土梦，此志几时酬',
'窗外晓山高积玉，梦回夜月更铺银',
'游兴亦难拘日阻，梦魂都不到人间',
'故国山川皆梦寐，旧家人物半丘墟',
'夜来清梦过城东，溪水分流径路通',
'半记不记梦觉后，似愁无愁情倦时',
'珊瑚枝下重相见，曾是鸳鸯梦里人',
'小曾与花为莫逆，梦作花神住花国',
'我亦泉石人，夙昔梦见之',
'颇爱乐天齐物我，梦随吟赏洛中桥',
'烟雨斑斓石藓春，坠云谁梦宝花颦',
'一击华鲸吼月明，主翁魂梦已惺惺',
'人间春信知多少，但觉轻寒入梦魂',
'定知今古皆春梦，不把功名作宿缘',
'欹枕皆归梦，同心只旧知',
'只与道人为鹤帐，始能清梦绕湖山',
'数家虽不成村落，一梦何曾到市朝',
'有梦诗将圣，无愁酒不神',
'梦中不记重泉隔，犹学儿童戏彩时',
'胡羯垂涎犹不悟，马嵬山底梦长安',
'春回陇首人千里，月到窗前梦五更',
