'平生何逊扬州梦，到得扬州月自寒',
'梦中记得春池绿，曾共丁宁下番花',
'自可曲肱惊短梦，南山丛薄有於菟',
'秋风倘未理归梦，我欲买船官渡头',
'一舸秋风梦亦寒，津人只作贾胡看',
'茅舍生苔费梦思，竹炉烹雪复何时',
'人间蚁蛭王侯梦，不到梅花纸帐边',
'十年梦不到清都，云满寒蓑雪满颅',
'分得山云老一瓢，梦寒不记紫宸朝',
'二十一年如梦过，五三六籍尚谁赓',
'春事已随蝴蝶梦，人情犹有杜鹃花',
'月明乌鹊占佳晤，莼老鲈鱼梦故关',
'人间富贵梦不到，世外高寒味尽长',
'月明昨夜欺寒梦，未了西斋竹外棋',
