'故国经年梦，寒窗独夜灯',
'中原山色外，残梦逐归鸿',
'不作膏粱梦，长令一剑随',
'万事皆如梦，谁知梦亦空',
'楚山不入清宵梦，月影蛩声满桂芗',
'江头曾梦见，髣髴此山川',
