'冻雨年催尽，羁愁梦作归',
'故国梅花梦，新年竹叶觞',
'湖海千年梦，家山亥日虚',
'昔梦来今雨，长怀入短歌',
'客程怀抱仍春潦，人事间关可梦魂',
'路入峡头天一握，梦回蓬背月三更',
