'遥知今夜空窗梦，只在江南水石间',
'分明点与诸人了，切忌朦胧在梦中',
'可怜波底蛾眉月，犹照他乡梦里人',
'十年心事今宵梦，千里家书昨日回',
'十年青史梦，只有老天知',
'江湖寥落转飘蓬，归梦年年逐去鸿',
'故人闲入梦，久雨颇妨脾',
'月明城上响边笳，一枕三更梦到家',
'一年两到吴兴郡，梦想往时云锦乡',
'怪得寒灯昨夜花，五更归梦倏还家',
'北窗清梦长，山间自啼鸟',
'夜夜劳梦魂，遥遥渡辽水',
'浮生等如梦，短长不须稽',
'乃知百年间，梦境匪长久',
'百年如大梦，梦里几纷驰',
'觉后识为梦，梦时曾未知',
'吾生今已觉，不记梦中时',
'在梦人无限，昏昏信可悲',
'多时不相逢，念尔魂梦飞',
'相对恍如梦，彼此白发新',
'自为山居人，梦寐亦安佚',
'征人家万里，梦向月中还',
