'西阁二年临昼梦，金刀一夕掩春芳',
'因香梦彻江南路，江水浮天月似霜',
'吟诗已得池塘梦，学易独明天地心',
'一梦何足凭，材名繇此出',
'静观人世人，颠倒醉梦中',
'百年浑是梦，万事付无心',
'近年书不至，远宦梦相随',
'往事浑如梦，长江不尽流',
'唤回浮世梦中梦，来向先生吟处吟',
