'夜来有梦到家山，苍筠翠干犹依然',
'班退归来清梦觉，红云犹自满衣襟',
'可人常入梦，簪盍几时同',
'有梦长如昔，无书直至今',
'却喜梦游黄鹤寺，几番携手月明中',
'思君三日雨，有梦付潮来',
'看翻后夜月囘照，梦忆前生地不同',
'梦临水月心先觉，看到霜空幻亦稀',
'梦游碧落风偏急，望断金精月正中',
'风雨昼酣秦地阔，关河春梦楚云低',
'昔谁醒中梦，今独梦中醒',
'参横月落梦何从，且领清香入盏中',
'夜深落月照颜色，端的宫袍入梦来',
'教人镫下看颜色，知得浮生一梦然',
