'江南景物可人意，梦里家山唤客愁',
'云山海月都抛却，嬴得庄周蝶梦长',
'三年梦招提，一笑来脱屣',
'屋头风雨交，唤此耋老梦',
'曲肱左省清梦余，长江拍拍天一隅',
'百年兀兀且饱睡，梦事有无浑不记',
'野馆梦回花似霰，戍楼诗就月如霜',
'三十余年一梦同，向来朝士尽沈空',
'归来劳梦侵，令人欲高遁',
'寸心灰尽周公梦，不恋朝衣只恋山',
