'石佛梦中来，天手造容貌',
'钩帘到面清风远，唤梦吟鶑白日长',
'山高日易斜，梦短夜分寂',
'醉来一枕华胥梦，肯校人间是与非',
'世间物化浑如梦，梦里惺惺却自由',
'因君撩我强题诗，却忆当年梦里时',
'从今不入襄王梦，剪尽巫山一朵云',
'多少玉人魂梦断，不胜情况恨更长',
'怀人更作梦千里，归思欲迷云一滩',
'三十年前曾见梦，兹游端可冠平生',
