'泗水昔年曾梦到，拜恩何幸接鹓鸿',
'一日驰声动黄阁，几回飞梦绕长安',
'心醉归来书文室，却怪前宵梦椽笔',
'开岁逢人日，吾衰不梦周',
'当年楚国山犹在，千古襄王梦不成',
'不见徐侯久，梦绕西山阳',
'虽同一床各做梦，政恐不妨人作乐',
'问梦是想理既剖，杯中有蛇心不疑',
'别后梦寒灯火夜，归来眼冷江湖秋',
'梦觉疏钟鸣远寺，一池明月芰荷香',
'苦憎茶扰人，能妨春梦长',
'流水三春逝，黄粱一梦虚',
'解佩时时梦汉滨，不将喜事报交亲',
'旧游颇念秦郎中，梦里五年如历指',
'梦回四贤篇，长风吹人醒',
'饱去定知频梦与，醉中何至便妨禅',
'故应疑我梦得官，谁信吾衰已无复',
'云霄才业逝川东，学易年龄一梦中',
'到今持梦渡杨澜，浪花漫天浩无极',
'自嗟匏系天一角，睫交去梦渺难追',
'阿环梦回如堕云，砚中玉纤如醉文',
'此生一梦耳，梦觉试寻绎',
'僧房借榻营夜语，灯火照人如梦寐',
'安得却如清梦中，杖履追随长尔汝',
'人生一梦耳，勿作镜中叹',
'遥知旅枕生清梦，梦到江南春好处',
'我亦不羁人，梦境聊戏剧',
'梦清不敢归，鲸浪溅天白',
'犹疑是梦中，惊定无所睹',
'思归念云山，夜梦亦成趣',
'朝来真见之，了非梦时遇',
'坐令应手开天葩，不因笔端梦生花',
'又如梦中人，饥而获饮食',
'不画凌烟大羽箭，来写山林梦幻身',
'解空勿忆南泉老，但言如梦不言无',
'此生一寄耳，梦幻相拘縻',
'梦中忧患自临巇，乌靴长恨涴尘泥',
'已觉无乡梦，今真是故山',
'梦冷寒庭半夜雨，幽欣临晓一番晴',
'诸方游遍浑如梦，古寺归来独掩扃',
'梦境消磨惊岁月，道乡仿佛见藩垣',
'往事已嗟如昨梦，壮怀无复似当年',
'锡响僧归帝青宝，梦香人宿水沉城',
'故应夜梦清苍胜，欲趁春光烂熳游',
'梦回清响春岩溜，夜久幽香喷水沈',
'人世百年蝴蝶梦，纷纷栩栩逐春繁',
'野寺闲眠听风雨，海山犹梦渡云涛',
'身闲已断思归梦，山好仍逢称意人',
'一官游戏且同尘，梦寐江湖亦可人',
'前时无际曾入梦，近日真游又得书',
'水餠槐芽动乡思，近来归梦与谁同',
'此夕乡关入归梦，明朝云物记曾书',
'明日旅亭劳昼梦，孤峰标格不容攀',
'谩劳清梦思相识，那料孤踪晚见知',
'意俱大地山河丧，心与空花梦幻生',
'夜来归梦清，疑在啼猿𪩘',
'倚筇笑语无人问，疑是西湖落梦中',
'清论不穷霏锯屑，故应云梦吐胸中',
