'家在严陵滩上住，风烟不是梦中看',
'此生正如此，梦觉两徐徐',
'远人无累超物表，云梦胸中吞芥子',
'十年如梦觉，两鬓自苍苍',
'一别仙山空梦寐，五年边塞走尘沙',
'几千里外相逢处，三十年间一梦惊',
'十年归梦在江湖，今日南飞塞雁孤',
'当年髣髴梦仙坞，今日分明在广寒',
'一樽笑语浑如梦，两地音尘动隔年',
