'天涯寓目徒增感，一觉钧天梦帝乡',
'梦中眉目尚分明，一过空堂百感生',
'颠倒一生浑是梦，寻思百计不如闲',
'论竹取云梦，不老不可少',
'一醉聊自适，醉梦归东吴',
'赖是丰年民气乐，梦回时见旐维旟',
'知谁吉梦如扬辇，一石龙驹落大霆',
'似闻阚泽中宵梦，月里分明有姓名',
