'恍然如梦寐，了不见往迹',
'五年三度过钟陵，马上春风醉梦醒',
'窗前邂逅一笑粲，梦中犹作在时看',
'咄嗟苟饮有时办，梦想溪堂何日成',
'北风如有齐安便，为报相思频梦君',
