'梦中曾说悟圆通，香水洗来蓦面唾',
'宿寺梦回莲叶雨，渡江衣冷荻花风',
'曾向梦中潜祐我，烁人仪表降蓬庐',
'家山久驻偷归梦，庭桧清含入夜钟',
'方客远书徒自得，牧人嘉梦合相先',
'剑水清凉梦笔山，戟衣照日启重关',
'不知许事付欢伯，醉著寒滩清梦长',
'五更山吐月，梦回人更幽',
'勤我十年梦，持公一瓣香',
'梦中逐客幻中归，荆楚瓯闽好赋诗',
'诗随鸿雁来春渚，梦逐蟾蜍入夜窗',
'遣我池塘梦春草，阿连风味剧堪怜',
