'绫衾倦梦愁淹卧，星鬓流年报早衰',
'草生宵梦传诗笔，梅析春酲托使邮',
'梦休孤蝶往，蜕在一蝉空',
'身孤惟夕梦，时到黼帷傍',
'一梦忽成霜蝶去，草深三迳若为眠',
