'司马胸中著云梦，杜陵眼底盖乾坤',
'梦为故国游，流涕指丘社',
'掉头不肯住，清宵梦沧浪',
'梦回陡觉衾裯薄，应是迷空一尺围',
'梦中十载因缘尽，又拄乌藤过别峰',
'三人证龟唤作鳖，哑子得梦向谁说',
