'徐卿有子何绝奇，熊罴惊梦初得之',
'每看禖燕日，已入梦熊篇',
'安得蘧蘧一觉梦，倚岩栩栩访庄周',
'声迹有妻先蝶梦，行藏无子付洴方',
'昨宵梦游兹树巅，环视谿山莽回互',
'困来石上眠，梦绕泉石闲',
'涅槃生死犹如梦，十圣三贤是阿谁',
'显迹灵光在，梦然一炷烟',
'几回客梦经秋雨，直至而今赁屋居',
'累生未了此真身，致使同他入梦户',
'首观梁武梦胡僧，未达修山龙济决',
'幻空如梦体，三昧觉华王',
'领得摩尼真宝藏，却来警梦表提纲',
'柳上一声莺，唤醒轮回梦',
'莫言闲人得睡足，梦到封侯亦劳碌',
'别意犹能在，应来梦里寻',
'东家有余材，凤衰无复梦',
'高鸿堕秋枕，归梦纷莫数',
'病悴优婆塞，归梦到松菊',
'幽寻胜践我亦喜，梦魂已落潇湘野',
