'且得小窗成好梦，片时江上逐烟蓑',
'初识宁和岭，有怀占梦时',
'独有还家梦，书窗一笑新',
'远游朔塞殊风景，梦到东阡看火耕',
'苍头呼梦杂鸡声，蘂杏诗来句转清',
'桥上垂纶装好梦，花边倚杖记前言',
'入梦无佳句，看云忆对床',
'我亦效吴蚕，踏破愁清梦',
'地占山川胜，小哉云梦游',
'半世别玉州，梦忆仙人掌',
'起起若为偿岁梦，嘻嘻无复对朝言',
