'竹声入清梦，夜客慰孤宿',
'渊源见云仍，梦泽吞八九',
'醉著山堂梦，初凉枕簟清',
'未成春草梦，先动白云思',
'青春随梦断，白发伴愁生',
'醉余和被拥，梦破觉窗明',
'廊庙𬣙谟外，丘园梦寐中',
