'君行为问灵泉水，梦到松林石壁前',
'密叶鸣琴清梦断，白云双眼暮山前',
'东壁梦初断，西山蕨正肥',
'灰心劳远梦，茧足蹈前言',
'茫然枝上鸟，伴我梦亦熟',
'佛庐尘不到，客枕梦频惊',
'佛狸莫梦淮边树，看揽长蛟下没渊',
