'因公唤醒推敲梦，此夕灯前忘却愁',
'物我境空鸡已木，功名梦断鹿犹蕉',
'舞翠梦回仙袂远，射雕人去露檐寒',
'仙子偶来成梦事，至今游客未尝闲',
'盘盘石磴红泉仙，春梦草断瑶池笺',
'丹穴呈九苞，夜梦或吐白',
'浊酒三杯投倦榻，梦回画被写吟情',
'香鼎灰寒午梦回，闲情谁与梦徘徊',
'角声吹断梅花梦，依旧枫湾半叶霜',
'华表柱头霜月冷，清宵有梦到钟声',
'欹枕北窗清梦觉，落红啼鸟伴幽人',
'诗如老杜吟东阁，梦约逋仙过断桥',
'梦骖鸾鹤相寻去，题遍江南寺寺诗',
'前生薝葡林中梦，到死旃檀国里香',
'法身兔角声闻外，尘事牛毛梦幻中',
'当时商家畚筑子，梦里撑船济川去',
'纱窗梦觉秋风度，疑是移家住广寒',
'风撼碧涛惊鹤梦，雷轰铁锁悦龙形',
'香山居士蓬莱院，借与王郎梦里看',
'芳草经年梦，幽禽隔径闻',
'幽人住城市，清梦两三重',
'愁极鬓成丝，沧江梦未归',
'梦觉跏趺不成寐，要伴禅和听二鼓',
'江草未圆青帝梦，香芸漏泄与梅花',
'世事真犹梦，人生瘦胜肥',
'客怀醉杀也醒醒，昨夜思家梦几惊',
'梦回蕉叶上，残雨几番鸣',
'山禽酣午梦，野菜健晨餐',
'盛丽悦其目，梦幻何足云',
'破晓频惊梦，叫云如解歌',
'洒若烦襟豁，悠然清梦长',
'句成春草梦，香带古梅寒',
'方拟来闻鹤，俄惊梦在蛇',
'西城纤巧仍如旧，祇慨梨云昨梦非',
'几番恶梦频惊散，一片闲愁顿扫清',
'伤心几载鸰原梦，洒泪今朝马鬣封',
'浮生一梦寄南柯，乌兔双驰迅若梭',
'梦魂恍而清，夜午超鸿蒙',
'梦觉两何有，闻打西林钟',
'梦破不成寐，茅斋坐清晓',
'吾生本疏庸，不作尘间梦',
'荣华不入梦，于焉谢忧责',
'出处虽小殊，梦寐常相求',
'解把浮生比梦中，肯计荣华与憔悴',
'金闺亦有梦，却行玉关道',
'视彼清凉月，感吾梦幻身',
'寒宵频作梦，曾不离吴城',
'鹫峰愁外远，巴峡梦中青',
'往事皆如梦，浮生底用忙',
'柳树垂阴密，苹花入梦香',
'乡远难为梦，山深易得秋',
'乡关成梦境，边月是愁媒',
'梦寐羊裘客，清游乐此邦',
'远客人谁到，空床梦独醒',
'他日难通信，想思梦寐劳',
'野鹤通秋梦，妖狐恐夜禅',
'保常同醉梦，曾有几人醒',
'前程行止谁能计，已悟浮生似梦中',
'行旅独看空感慨，池塘关梦自神奇',
'因悲窃国亡身者，枉作尘劳梦一场',
'交友后先同昨梦，老人八十尚他乡',
'客枕难成梦，秋宵转觉长',
'一声霜雁过，倦客梦初醒',
'愁多宛转结成梦，梦远直过西凉州',
'悲寝难成梦，愁餐不下咽',
'算年齐易卦，写梦入诗篇',
'道机应已熟，世梦莫教酣',
'孤身同梦幻，两鬓任霜雪',
'难教入凡梦，唯共保天真',
'迁客销魂惊梦寐，征人零泪湿衣裾',
'追思何异邯郸梦，瞬息光阴三十秋',
'梦后旧欢初髣髴，酒醒前事略依稀',
'台上喧呼成蝶梦，眼前零落空杨花',
