'昨夜过温汤，梦与杨妃浴',
'几日狂酲析，思君梦更劳',
'江南老守思离阔，梦想时过白鹭涛',
'悠悠晋溪上，水石挂清梦',
'红丝萦脍晓刀鸣，双龙笑断梦中惊',
'昼轩梦觉开前栊，画栏花草意气雄',
