'梦断维熊夜，祥呈馈鲤初',
'和如戏泚卢杞题，俨若梦令希烈怕',
'人生孰非梦，安有昏旦异',
'诗成聊假寐，归梦历层颠',
'百年客舍熟黄梁，梦境偶逢还偶别',
'只今追想如梦魂，更堪哦子阳关曲',
'遐想幽人居，梦过剡溪曲',
'梦随柔橹到西兴，舣舟步入龙山坞',
'争传绝似余杭标，十年梦想空飘飖',
'逸想在西兴，清梦不容逐',
'应怀此夕游，梦想亦清淑',
'竹鸡断幽梦，朦胧不能续',
'是身已作梦幻观，肯复经营此身外',
'梦幻有贵贱，譬如绵与芦',
'万乘扣扉宫月斜，梦惊呼烛度窗纱',
