'应思和月踏层冰，快意暗惊梦犹怕',
'鸣鸠惊午梦，意消风物闲',
'梦回书几有青灯，鸡一再鸣布衾暖',
'时应梦湘江，醉卧闻柔橹',
'马上续残梦，不复较迟速',
'双泉云树时到梦，神武门前思挂冠',
'诗成坐假寐，梦历秋山赤',
'神交梦成趣，意合气自激',
'慈亲未老身先逝，梦境悲欢成一戏',
'至今清夜梦，犹能历层颠',
'及其梦觉已，不过食顷耳',
'梦中先已逢祖师，异世曾同香火社',
'惯看青禁月，屡梦玉关尘',
'清境扶归梦，残缸替客愁',
'观身真作梦，视世一浮埃',
'白下门连寺，清游入梦中',
'晓窗应破梦，卧听鸟呼风',
'一宿路旁寺，霜清梦亦寒',
'试作吉祥卧，梦清如素秋',
'眼倦经长掩，身闲梦亦清',
'竹窗催梦雨，兰室对祥灯',
'毎劳孤枕梦，时过小溪桥',
'梦泽於菟三口视，丹山雏凤九苞文',
'梦里绪言犹可记，壁间遗像尚依然',
'却信真人还有梦，岂关禅子未忘机',
'懒复小窗邀独秀，却应归梦挂双峰',
'放箸翛然庐岳去，门栏他日梦应频',
