'镜中白髪今慵剃，梦里浮华已懒争',
'懒于梦境分能所，枉把情缘比客尘',
'深掩圜扉夜向阑，梦惊清境慰辛酸',
'身健已如秋社燕，梦回犹看客亭炊',
'鸟工魂梦寻公去，蝉蜕尘埃出郭来',
'梦幻此身犹且在，杖藜投老得追游',
'清景骨飞嗟未到，故应唯许梦魂通',
'花异空怀上林苑，梦清疑宿广寒宫',
'被冷夜晴成好梦，马随香雾入修门',
'致坡入梦殊堪纪，与俨忘形亦自贤',
'逢山有寺幽欣集，对客开轩午梦清',
'夜久饥鼯嗅空案，梦惊鬭虎堕层崖',
'意处世间离生灭，梦中尘劫浪遮藏',
'梦里寻音响，教休定不甘',
'万法如有功，梦事应存体',
'唾雾珠消君勿笑，梦回比物镇长灵',
'谁似梦中忧患里，饭余要睡即齁齁',
'思虑不及犹为物，分别未忘都是梦',
'多谢炼磨金出矿，敢辞枷鏁梦中身',
'闲人忙事莫参差，各梦同床暗发嗟',
'枕臂聊为吉祥卧，雪猿声与梦俱清',
'何处干戈能胁吓，谁家梦幻敬追奔',
'汝心有罅隙，甘受梦幻缚',
'君看火力初无情，圣凡伪真俱发梦',
'生死鹘仑谁擘破，披露梦中根境法',
'梦想天平紫府开，却嗟匏系在铜台',
'丹心忧国梦魂间，祗恐清霄亦未闲',
'衰谢何堪抚鸣剑，梦魂犹拟灭羌戎',
'尚有素怀思报国，可怜幽梦欲平戎',
'羸驱岂愿留湖外，清梦时惊到海壖',
'隐几助成春草梦，卷帘饶占比窗凉',
'古来除梦卜，真得几英雄',
'幽窗残梦午声鸡，犬吠人家草舍微',
'知是高轩应倒屣，妙谈全胜梦周公',
'须知荣贵南柯梦，且尽勤渠北海樽',
'我已梦为蝶，咄哉为罢休',
'惟应付梦幻，事已共一笑',
'看山眼已足，涉险梦犹怕',
'去乡三十年，梦寐犹西土',
'凛然七尺躯，云梦不足吞',
'那知羁旅怀，扁舟梦江湖',
'邯郸一梦破，怀抱良蹁跹',
'作诗慰所思，梦绕池塘草',
'劳生养此梦幻躯，谁能华睆慕大夫',
'梦里寻归计，柴桑似有涯',
'纺妪固尝占异梦，肉芝还已献畸人',
'绝口谁能论梦幻，逢人聊祇话耕桑',
'黄粱正与梦俱熟，环堵典无爨欲清',
'敢嫌仲蔚蓬蒿陋，久悟邯郸梦幻中',
'荣枯梦已破，何待邯郸记',
'岂无谪仙梦，萧散到泉石',
'邂逅话畴昔，恍恍一梦余',
'扁舟明发处，应记梦华胥',
'尘沙惊老眼，江海梦归程',
'簿领三年梦，尘沙两鬓霜',
'惊回十二年前梦，陈迹依然泪满巾',
'物外胜游方自适，枕边幽梦忽惊残',
'官学半生浑似梦，尘埃两眼渐生花',
