'十载光阴如梦觉，半生簿领尚桴浮',
'午枕昏昏迎好梦，斋房寂寂称幽人',
'几年尘土客京华，梦到西湖佛子家',
'骨冷破梦境，虚窗坐黎明',
'凡诸有为法，实如幻泡梦',
'清寒逼吟魄，不起梨云梦',
'漆园信知鱼，非惟常梦蝶',
'俄然正梦半山老，练裙葛帔泉石间',
'榻施籧篨独展转，梦觉不离周孔间',
'息黥补劓有甘寝，梦觉起作游山行',
'有车乘下泽，无梦入高唐',
'喜君句法无糕字，始信才华梦得同',
'饮罢清风引仙阙，睡余妖梦破朝云',
