'梦到逍遥大庭馆，不堪檐外鸟惊回',
'栩栩梦魂成独往，翩翩书札慰相思',
'畏酒游扬梦，因诗点染愁',
'蛮国戈矛真梦幻，醉乡风露别乾坤',
'称讥等梦事，缓带耳不领',
'夜梦嵇阮辈，醉乡须少留',
'华鲸破短梦，山禽唤新句',
'西家有胜士，梦回笔生花',
'客梦漳水头，邻鸡鸣枯楬',
'苦心梦吐凤，流传今未央',
'放船云梦鬼作祟，磈磊仆卧洪涛中',
'觅句何劳梦惠连，解颐未用呼匡鼎',
'梦泽张侯饱闲暇，直疑胸中有成画',
'自从寂绝牛头梦，力振家声合在兹',
'日下涢川暮，烟横梦泽秋',
'须知百岁都为梦，未信千金买得闲',
'几宵惊客梦，半夜有猿吟',
'人比鸣琴令，官参梦马卿',
'梦随归云欲访之，邻垣华鲸喧枕底',
'好饮酒储尽，少眠茶梦稀',
'游观如昨梦，换谢若晨炊',
'午梦蛮花湿，晚凉衣带秋',
'霜风吹晓角，梦听小单于',
'梦中未觉关河远，枕底忽闻钟鼓传',
'支床梦破严城角，决眦风回落雁洲',
'天上汉庭劳梦寐，峤南殷鉴恐羁縻',
'雨打船篷藏枉渚，钟残客梦忆禅林',
'高斋解榻留我宿，破梦惊涛翻疾雷',
