'诗来或作破客梦，语妙直堪排帝阍',
'兴深杯杓怀山简，勾梦池塘忆惠连',
'幽禽唤起醉乡梦，疑在故园茅屋边',
'孤云两角真在梦，一抹寒林古木深',
'梦想何尝到，阶升信有缘',
'梦寻汤饼到，风入茶瓯生',
'投床梦婉娩，日永贪睡美',
'飘霙半夜入，方梦踏云路',
'穷通等梦幻，思虑自枨触',
'八年杖屦隔，坐睡梦嵩少',
'梦中闻版响，觉后虾蟆啼',
