'清梦渺春草，俚谈羞杕杜',
'前对百尺井，梦中闻辘轳',
'向来围城厄，梦想音信断',
'青灯吐吞帏幔间，竹风吹衾梦初圆',
'猗兰成断梦，素柰陨空花',
'咄咄劳生梦，真成一洗空',
'半世纷纭惊似梦，一官潦倒信平生',
'武林旧话终成梦，旅榇空归泪满巾',
'苦无好梦绝江去，合有短书逢雁回',
'梦入向来招隐处，诗成有味付谁看',
'翠簟轻纨腹果然，午风吹梦入湖边',
